import * as Sentry from "@sentry/nextjs";
import { redirect } from "next/navigation";
import type { Metadata } from "next";
import { createClient } from "@/lib/supabase/server";
import { Container } from "@/components/layout/Container";
import { GlassCard } from "@/components/ui/GlassCard";
import { Badge } from "@/components/ui/Badge";
import { USER_MANAGEMENT_API_URL, APP, PRICING } from "@/lib/constants";
import { SignOutButton } from "@/components/auth/SignOutButton";
import { ProfileEditor } from "@/components/account/ProfileEditor";
import { EmailPreferences } from "@/components/account/EmailPreferences";
import { DeleteAccountSection } from "@/components/account/DeleteAccountSection";
import { ManageSubscriptionButton } from "@/components/pricing/ManageSubscriptionButton";
import { PricingSection } from "@/components/pricing/PricingSection";
import { PricingCard } from "@/components/pricing/PricingCard";

export const metadata: Metadata = {
  title: "Account",
};

interface Entitlement {
  entitlementId: string;
  status: string;
  expiresAt: string | null;
  productIdentifier: string | null;
  store: string;
}

interface EmailPreferences {
  marketing: boolean;
  productUpdates: boolean;
  transactional: boolean;
}

const EMAIL_PREFS_DEFAULTS: EmailPreferences = {
  marketing: true,
  productUpdates: true,
  transactional: true,
};

async function getEmailPreferences(accessToken: string): Promise<EmailPreferences> {
  try {
    const res = await fetch(`${USER_MANAGEMENT_API_URL}/api/me/email-preferences`, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
    if (res.status === 404) return EMAIL_PREFS_DEFAULTS;
    if (!res.ok) {
      Sentry.captureMessage(`Email preferences fetch failed: ${res.status}`, {
        level: "error",
        tags: { service: "user-management", action: "getEmailPreferences" },
        extra: { status: res.status },
      });
      return EMAIL_PREFS_DEFAULTS;
    }
    return (await res.json()) as EmailPreferences;
  } catch (err) {
    Sentry.captureException(err, {
      tags: { service: "user-management", action: "getEmailPreferences" },
    });
    return EMAIL_PREFS_DEFAULTS;
  }
}

async function getEntitlements(accessToken: string): Promise<Entitlement[]> {
  try {
    const res = await fetch(`${USER_MANAGEMENT_API_URL}/api/me/entitlements`, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
    if (!res.ok) {
      Sentry.captureMessage(`Entitlements fetch failed: ${res.status}`, {
        level: "error",
        tags: { service: "user-management", action: "getEntitlements" },
        extra: { status: res.status },
      });
      return [];
    }
    const data = (await res.json()) as { entitlements?: Entitlement[] };
    return data.entitlements ?? [];
  } catch (err) {
    Sentry.captureException(err, {
      tags: { service: "user-management", action: "getEntitlements" },
    });
    return [];
  }
}

function Avatar({ url, name }: { url?: string; name: string }) {
  if (url) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img src={url} alt={name} className="h-16 w-16 rounded-full" referrerPolicy="no-referrer" />
    );
  }

  const initial = name.charAt(0).toUpperCase();
  return (
    <div className="flex h-16 w-16 items-center justify-center rounded-full bg-accent text-h3 font-semibold text-heading">
      {initial}
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    active: "bg-accent/20 text-accent-hover",
    trialing: "bg-accent/20 text-accent-hover",
    expired: "bg-danger/15 text-danger",
    grace_period: "bg-danger/15 text-danger",
  };

  return (
    <span
      className={`inline-flex rounded-full px-3 py-1 text-xs font-medium ${colors[status] ?? "bg-surface-muted text-body"}`}
    >
      {status.replace("_", " ")}
    </span>
  );
}

export default async function AccountPage() {
  if (!process.env.NEXT_PUBLIC_SUPABASE_URL || !process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY) {
    redirect("/login");
  }

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/login");
  }

  const {
    data: { session },
  } = await supabase.auth.getSession();

  const [entitlements, emailPrefs] = await Promise.all([
    session ? getEntitlements(session.access_token) : Promise.resolve([]),
    session ? getEmailPreferences(session.access_token) : Promise.resolve(EMAIL_PREFS_DEFAULTS),
  ]);

  const activeEntitlements = entitlements.filter(
    (e) => e.status === "active" || e.status === "trialing",
  );

  const displayName =
    user.user_metadata.full_name ?? user.user_metadata.name ?? user.email ?? "User";
  const avatarUrl = user.user_metadata.avatar_url as string | undefined;
  const provider = user.app_metadata.provider ?? "email";

  return (
    <section className="section-y">
      <Container narrow>
        <h1 className="text-h1 font-medium text-heading">Account</h1>

        {/* Profile */}
        <GlassCard className="mt-8">
          <div className="flex items-center gap-5">
            <Avatar url={avatarUrl} name={displayName} />
            <div>
              <p className="mt-1 text-sm text-body">{user.email}</p>
              <Badge className="mt-2 px-3 py-1 text-xs">{provider}</Badge>
            </div>
          </div>
          <div className="mt-6 border-t border-line pt-6">
            <ProfileEditor initialName={displayName} />
          </div>
        </GlassCard>

        {/* Subscription */}
        <GlassCard className="mt-6">
          <h2 className="text-h3 font-semibold text-heading">Subscription</h2>

          {activeEntitlements.length > 0 ? (
            <div className="mt-4 space-y-4">
              {activeEntitlements.map((e) => (
                <div
                  key={e.entitlementId}
                  className="flex items-center justify-between rounded-xl bg-surface-muted border border-line p-4"
                >
                  <div>
                    <p className="font-medium text-heading">{APP.premiumTier}</p>
                    <p className="mt-1 text-sm text-body">
                      {e.productIdentifier} · {e.store.replace("_", " ")}
                    </p>
                    {e.expiresAt && (
                      <p className="mt-1 text-xs text-muted">
                        Renews{" "}
                        {new Date(e.expiresAt).toLocaleDateString("en-US", {
                          month: "long",
                          day: "numeric",
                          year: "numeric",
                        })}
                      </p>
                    )}
                  </div>
                  <StatusBadge status={e.status} />
                </div>
              ))}
              <div className="mt-4">
                <ManageSubscriptionButton />
              </div>
            </div>
          ) : (
            <div className="mt-4">
              <p className="font-medium text-heading">You&apos;re on the Free plan</p>
              <p className="mt-1 text-sm text-body">
                Upgrade to {APP.premiumTier} for unlimited identifications and personalized care
                schedules.
              </p>

              <PricingSection signedIn proCtaLabel="Upgrade">
                <PricingCard
                  name="Free"
                  price="$0"
                  period="forever"
                  features={PRICING.features.free}
                  badge="Current"
                >
                  <span className="inline-flex h-[54px] w-full max-w-[329px] items-center justify-center rounded-[20px] border border-line bg-surface-muted text-sm font-medium text-body">
                    Your current plan
                  </span>
                </PricingCard>
              </PricingSection>
            </div>
          )}
        </GlassCard>

        {/* Email Preferences */}
        <GlassCard className="mt-6">
          <h2 className="text-h3 font-semibold text-heading">Email Preferences</h2>
          <div className="mt-4">
            <EmailPreferences
              initialPreferences={{
                marketing: emailPrefs.marketing,
                productUpdates: emailPrefs.productUpdates,
              }}
            />
          </div>
        </GlassCard>

        {/* Sign out */}
        <div className="mt-8">
          <SignOutButton />
        </div>

        {/* Account deletion */}
        <DeleteAccountSection />
      </Container>
    </section>
  );
}

