"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { createClient } from "@/lib/supabase/client";
import { REVENUECAT_PURCHASE_LINK } from "@/lib/constants";
import { Container } from "@/components/layout/Container";
import { GlassCard } from "@/components/ui/GlassCard";
import { Button } from "@/components/ui/Button";

export function CheckoutClient() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const plan = searchParams.get("plan") ?? "";

  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const startedRef = useRef(false);

  useEffect(() => {
    if (startedRef.current) return;
    startedRef.current = true;

    async function run() {
      if (!plan) {
        router.replace("/pricing");
        return;
      }

      if (!REVENUECAT_PURCHASE_LINK) {
        setErrorMessage(
          "Checkout isn't configured yet. Please try again later or contact support.",
        );
        return;
      }

      const supabase = createClient();
      const {
        data: { session },
      } = await supabase.auth.getSession();

      if (!session) {
        router.replace(`/login?next=${encodeURIComponent(`/checkout?plan=${plan}`)}`);
        return;
      }

      const successUrl = `${window.location.origin}/account?checkout=success`;
      const purchaseUrl = new URL(
        `${REVENUECAT_PURCHASE_LINK}/${encodeURIComponent(session.user.id)}`,
      );
      purchaseUrl.searchParams.set("package_id", plan);
      purchaseUrl.searchParams.set("success_url", successUrl);
      window.location.href = purchaseUrl.toString();
    }

    run();
  }, [plan, router]);

  return (
    <section className="section-y">
      <Container narrow>
        <GlassCard className="p-8 text-center">
          {errorMessage ? (
            <>
              <h1 className="text-h2 font-medium text-heading">Checkout unavailable</h1>
              <p className="mt-3 text-sm text-body">{errorMessage}</p>
              <div className="mt-6 flex justify-center">
                <Button as="a" href="/pricing" variant="secondary">
                  Back to pricing
                </Button>
              </div>
            </>
          ) : (
            <>
              <h1 className="text-h2 font-medium text-heading">Redirecting to checkout…</h1>
              <p className="mt-3 text-sm text-body">
                Hold tight, we&apos;re sending you to our secure payment page.
              </p>
            </>
          )}
        </GlassCard>
      </Container>
    </section>
  );
}

