"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase/client";
import { Button } from "@/components/ui/Button";
import { GlassCard } from "@/components/ui/GlassCard";
import { USER_MANAGEMENT_API_URL } from "@/lib/constants";

function ConfirmationDialog({
  onConfirm,
  onCancel,
}: {
  onConfirm: () => void;
  onCancel: () => void;
}) {
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") onCancel();
    },
    [onCancel],
  );

  useEffect(() => {
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-heading/60 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="delete-dialog-title"
    >
      <GlassCard className="mx-4 max-w-md p-8">
        <h3 id="delete-dialog-title" className="text-h3 font-semibold text-heading">
          Delete your account?
        </h3>
        <p className="mt-3 text-sm text-body leading-relaxed">
          This will permanently delete your account and all associated data immediately. This cannot
          be undone.
        </p>
        <div className="mt-6 flex gap-3">
          <Button variant="ghost" fullWidth={false} onClick={onCancel}>
            Cancel
          </Button>
          <button
            onClick={onConfirm}
            className="rounded-[20px] bg-danger px-5 py-3 text-sm font-medium text-white transition-opacity hover:opacity-90"
          >
            Delete my account
          </button>
        </div>
      </GlassCard>
    </div>
  );
}

export function DeleteAccountSection() {
  const router = useRouter();
  const [showDialog, setShowDialog] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleDelete() {
    setLoading(true);
    setError(null);
    setShowDialog(false);

    const supabase = createClient();
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (!session) {
      setLoading(false);
      return;
    }

    try {
      const res = await fetch(`${USER_MANAGEMENT_API_URL}/api/me`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${session.access_token}` },
      });

      if (!res.ok) {
        setError("Failed to delete account. Please try again.");
        return;
      }

      await supabase.auth.signOut();
      router.push("/login");
    } catch {
      setError("Failed to delete account. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mt-8">
      <GlassCard>
        <h2 className="text-h3 font-semibold text-heading">Danger zone</h2>
        <p className="mt-2 text-sm text-body">
          Permanently delete your account and all associated data.
        </p>
        <div className="mt-4">
          <button
            onClick={() => setShowDialog(true)}
            disabled={loading}
            className="rounded-[20px] border border-danger/30 bg-transparent px-5 py-3 text-sm font-medium text-danger transition-colors hover:bg-danger/10"
          >
            Delete account
          </button>
        </div>
      </GlassCard>

      {error && <p className="mt-3 text-sm text-danger">{error}</p>}

      {showDialog && (
        <ConfirmationDialog onConfirm={handleDelete} onCancel={() => setShowDialog(false)} />
      )}
    </div>
  );
}

