"use client";

import { useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { ToggleSwitch } from "@/components/ui/ToggleSwitch";
import { USER_MANAGEMENT_API_URL } from "@/lib/constants";

interface EmailPreferencesProps {
  initialPreferences: {
    marketing: boolean;
    productUpdates: boolean;
  };
}

export function EmailPreferences({ initialPreferences }: EmailPreferencesProps) {
  const [marketing, setMarketing] = useState(initialPreferences.marketing);
  const [productUpdates, setProductUpdates] = useState(initialPreferences.productUpdates);
  const [error, setError] = useState<string | null>(null);
  const [isUpdating, setIsUpdating] = useState(false);

  async function updatePreference(
    field: keyof EmailPreferencesProps["initialPreferences"],
    value: boolean,
  ) {
    setError(null);
    setIsUpdating(true);

    try {
      const supabase = createClient();
      const {
        data: { session },
      } = await supabase.auth.getSession();
      if (!session) return false;

      const res = await fetch(`${USER_MANAGEMENT_API_URL}/api/me/email-preferences`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${session.access_token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ [field]: value }),
      });

      if (!res.ok) {
        setError("Failed to update preference. Please try again.");
        return false;
      }

      return true;
    } catch {
      setError("Failed to update preference. Please try again.");
      return false;
    } finally {
      setIsUpdating(false);
    }
  }

  async function handleMarketingToggle(value: boolean) {
    setMarketing(value);
    const success = await updatePreference("marketing", value);
    if (!success) setMarketing(!value);
  }

  async function handleProductUpdatesToggle(value: boolean) {
    setProductUpdates(value);
    const success = await updatePreference("productUpdates", value);
    if (!success) setProductUpdates(!value);
  }

  return (
    <div className="flex flex-col gap-5">
      <div>
        <ToggleSwitch
          id="marketing"
          label="Marketing emails"
          checked={marketing}
          onChange={handleMarketingToggle}
          disabled={isUpdating}
        />
        <p className="mt-1 text-xs text-body">
          Tips, promotions, and news about Save My Cactus products.
        </p>
      </div>

      <div>
        <ToggleSwitch
          id="product-updates"
          label="Product updates"
          checked={productUpdates}
          onChange={handleProductUpdatesToggle}
          disabled={isUpdating}
        />
        <p className="mt-1 text-xs text-body">New features, improvements, and release notes.</p>
      </div>

      {error && <p className="text-sm text-danger">{error}</p>}
    </div>
  );
}
